const egySothicDays=()=>1461*EGY_CIVIL_YEAR;

const CHRON_J2000_JDN=2451545;

const chronJDN=days=>days+CHRON_J2000_JDN;

const chronMayaDays=days=>chronJDN(days)-MAYA_GMT_JDN;

const chronPhases=(epochDays)=>{
  const md=Math.floor(chronMayaDays(epochDays));
  const jdn=chronJDN(epochDays);
  const cr=mayaCalendarRound(), so=egySothicDays();
  const wrap=(x,n)=>((x%n)+n)%n;
  return {
    long_count_days:md,
    tzolkin_phase:wrap(md,MAYA_TZOLKIN)/MAYA_TZOLKIN,
    haab_phase:wrap(md,MAYA_HAAB)/MAYA_HAAB,
    calendar_round_phase:wrap(md,cr)/cr,
    /* the ganzhi DAY count: sixty days, not the sixty YEARS the wheels turn in. The
       two share a name and a length and are different cycles, which is why they are
       published under different keys and neither is an alias of the other. */
    sexagenary_phase:wrap(Math.floor(epochDays),60)/60,
    egyptian_civil_phase:Math.floor(wrap(jdn-EGY_NABONASSAR_JDN,EGY_CIVIL_YEAR))/EGY_CIVIL_YEAR,
    sothic_phase:wrap(jdn,so)/so};
};

