const wotPhase=(id,epochDays)=>{
  const T=WOT_TRADITIONS.find(t=>t.id===id); if(!T) return null;
  if(T.phase==='structure'||!T.turnDays) return null;
  if(T.phase==='declared'){
    /* a yuga phase exists only once the doctrinal Kali epoch is accepted, and this
       says so by taking it from a named constant rather than from thin air */
    const d=chronJDN(epochDays)-WOT_KALI_START_JDN;
    const kali=WOT_YUGA_YR[3]*365.2422;
    return ((d/kali)%1+1)%1;
  }
  /* its own era where the atlas has one, and a stated fixed instant where it does not */
  const d=chronJDN(epochDays)-(WOT_EPOCHS[T.id]??MAYA_GMT_JDN);
  return ((d/T.turnDays)%1+1)%1;
};

