const LTP_S=Math.PI/(180*3600), LTP_EPS0=84381.406*LTP_S;

const LTP_EQU_POL=[[5453.282155,0.4252841,-0.00037173,-0.000000152],
                   [-73750.930350,-0.7675452,-0.00018725,0.000000231]];

