function nsyEnvironment(id){ return NSY_ENVIRONMENTS.filter(e=>e.id===id)[0]||null; }

const NSY_SOLAR=Object.freeze({hydrogen:0.7381, helium:0.2485, metals:0.0134});

const DL_AU=1.495978707e11;

const DL_ARCSEC=Math.PI/(180*3600);

const DL_PARSEC=DL_AU/Math.tan(DL_ARCSEC);

const DL_PARSEC_SMALL=DL_AU/DL_ARCSEC;

const DL_LY=9.4607304725808e15;

const dLadDistanceFromParallax=mas=>(mas>0)?1000/mas:Infinity;

function dLadParallaxReach(sigmaMas,fractionalError){
  if(!(sigmaMas>0)||!(fractionalError>0)) return 0;
  return 1000/(sigmaMas/fractionalError);
}

const DL_CEPH_SLOPE=-2.81;

const DL_CEPH_ZERO=-4.05;

const dLadCepheidM=(P,slope,zero)=>(slope==null?DL_CEPH_SLOPE:slope)*(Math.log10(P)-1)+(zero==null?DL_CEPH_ZERO:zero);

function dLadCepheidDistance(P,mApp,slope,zero){
  const M=dLadCepheidM(P,slope,zero);
  return dLadDistanceFromModulus(mApp-M);
}

const dLadModulus=pc=>5*Math.log10(pc/10);

const dLadDistanceFromModulus=mu=>10*Math.pow(10,mu/5);

const dLadModulusExtinguished=(pc,aV)=>dLadModulus(pc)+(aV||0);

const DL_IA_M=-19.3;

const dLadIaReach=(mLimit,M)=>dLadDistanceFromModulus(mLimit-(M==null?DL_IA_M:M));

const DL_H0=Object.freeze([
  {id:'planck', t:['Planck 2018 · the microwave background, through a model',
                   'Planck 2018 · реликтовое излучение через модель','Planck 2018'],
   value:67.66, sigma:0.42, kind:'early'},
  {id:'shoes',  t:['SH0ES · the ladder, climbed','SH0ES · пройденная лестница','SH0ES'],
   value:73.04, sigma:1.04, kind:'late'},
  {id:'trgb',   t:['TRGB · the tip of the red giant branch, a third route',
                   'TRGB · вершина ветви красных гигантов','TRGB'],
   value:69.8, sigma:1.9, kind:'late'}
]);

function dLadTension(a,b){
  const s=Math.hypot(a.sigma,b.sigma);
  const d=Math.abs(a.value-b.value);
  return {difference:d, combined_sigma:s, sigma:(s>0)?d/s:Infinity,
    fraction:d/Math.min(a.value,b.value),
    /* the one number that matters: how big a magnitude systematic would have to
       hide somewhere in the ladder for these to be the same measurement */
    magnitude_systematic:5*Math.log10(Math.max(a.value,b.value)/Math.min(a.value,b.value))};
}

const dLadH0FromShift=(h0,dm)=>h0*Math.pow(10,-dm/5);

const dLadMagnitudesToFraction=dm=>Math.pow(10,dm/5)-1;

const DL_RUNGS=Object.freeze([
  {id:'parallax', t:['geometric parallax','геометрический параллакс','geometrische Parallaxe'],
   sigma_mag:0.02, systematic_mag:0.01, reach_pc:5e3,
   note:'the only rung that is not calibrated against anything: a triangle with the Earth`s orbit as its base'},
  {id:'cepheid',  t:['Cepheid period-luminosity','зависимость период–светимость','Perioden-Leuchtkraft-Beziehung'],
   sigma_mag:0.03, systematic_mag:0.03, reach_pc:4e7,
   note:'Leavitt had the slope in 1912 and never the zero point; it still comes from below'},
  {id:'typeia',   t:['type Ia supernovae','сверхновые типа Ia','Typ-Ia-Supernovae'],
   sigma_mag:0.05, systematic_mag:0.03, reach_pc:2e9,
   note:'standardisable, not standard: the width-luminosity correction is fitted'}
]);

function dLadChain(rungs){
  const R=rungs||DL_RUNGS;
  let rand=0, sys=0;
  const steps=[];
  for(const r of R){
    rand=Math.hypot(rand,r.sigma_mag);
    sys+=r.systematic_mag;
    steps.push({id:r.id, cumulative_random_mag:rand, cumulative_systematic_mag:sys,
      cumulative_distance_error:dLadMagnitudesToFraction(Math.hypot(rand,sys)),
      reach_pc:r.reach_pc});
  }
  return {steps, random_mag:rand, systematic_mag:sys,
    total_mag:Math.hypot(rand,sys),
    total_fraction:dLadMagnitudesToFraction(Math.hypot(rand,sys))};
}

const GYRO_A=0.7725;

const GYRO_B=0.601;

const GYRO_N=0.5189;

const GYRO_BV_MIN=0.40;

const GYRO_SUN_AGE_GYR=4.57;

const gyroColourTerm=bv=>GYRO_A*Math.pow(Math.max(1e-9,bv-GYRO_BV_MIN),GYRO_B);

const gyroAgeMyr=(bv,periodDays)=>Math.pow(Math.max(1e-12,periodDays)/gyroColourTerm(bv),1/GYRO_N);

const gyroAgeGyr=(bv,periodDays)=>gyroAgeMyr(bv,periodDays)/1000;

const GYRO_BALL_K=4600;

const GYRO_BALL_A=0.92;

const GYRO_BALL_P=1.7;

const GYRO_BALL_Q=0.62;

const gyroTeffFromBV=bv=>GYRO_BALL_K*(1/(GYRO_BALL_A*bv+GYRO_BALL_P)
                                     +1/(GYRO_BALL_A*bv+GYRO_BALL_Q));

const gyroBVFromTeff=teff=>{ if(!(teff>0)) return null;
  let lo=-0.35, hi=3.0;
  for(let i=0;i<120;i++){ const m=(lo+hi)/2;
    if(gyroTeffFromBV(m)>teff) lo=m; else hi=m; }
  return (lo+hi)/2; };

const gyroBreakTeff=()=>gyroTeffFromBV(GYRO_BV_MIN);

