const Z3_DAU=149597870.7e3, Z3_DAYSEC=86400, Z3_DJY=365.25, Z3_DR2AS=206264.8062470963551564734;

const Z3_AULT=Z3_DAU/299792458, Z3_DC=Z3_DAYSEC/Z3_AULT;

const z3Pdp=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];

const z3Pm=a=>Math.sqrt(z3Pdp(a,a));

function z3S2pv(th,ph,r,td,pd,rd){
  const st=Math.sin(th),ct=Math.cos(th),sp=Math.sin(ph),cp=Math.cos(ph),
        rcp=r*cp,x=rcp*ct,y=rcp*st,rpd=r*pd,w=rpd*sp-cp*rd;
  return [[x,y,r*sp],[-y*td-w*ct,x*td-w*st,rpd*cp+sp*rd]]; }

function z3Pv2s(pv){
  let [x,y,z]=pv[0]; const [xd,yd,zd]=pv[1];
  let rxy2=x*x+y*y, r2=rxy2+z*z; const rtrue=Math.sqrt(r2); let rw=rtrue;
  if(rtrue===0){ x=xd; y=yd; z=zd; rxy2=x*x+y*y; r2=rxy2+z*z; rw=Math.sqrt(r2); }
  const rxy=Math.sqrt(rxy2), xyp=x*xd+y*yd;
  let th,ph,td,pd;
  if(rxy2!==0){ th=Math.atan2(y,x); ph=Math.atan2(z,rxy); td=(x*yd-y*xd)/rxy2; pd=(zd*rxy2-z*xyp)/(r2*rxy); }
  else { th=0; ph=z!==0?Math.atan2(z,rxy):0; td=0; pd=0; }
  return {th,ph,r:rtrue,td,pd,rd:rw!==0?(xyp+z*zd)/rw:0}; }

function z3Starpv(ra,dec,pmr,pmd,px,rv){
  const PXMIN=1e-7, VMAX=0.5, IMAX=100;
  let iwarn=0, w;
  if(px>=PXMIN) w=px; else { w=PXMIN; iwarn=1; }
  const r=Z3_DR2AS/w, rd=Z3_DAYSEC*rv*1e3/Z3_DAU, rad=pmr/Z3_DJY, decd=pmd/Z3_DJY;
  const pv=z3S2pv(ra,dec,r,rad,decd,rd);
  if(z3Pm(pv[1])/Z3_DC>VMAX){ pv[1]=[0,0,0]; iwarn+=2; }
  const pr=z3Pm(pv[0]), x=pv[0].map(c=>c/pr),
        vsr=z3Pdp(x,pv[1]), usr=x.map(c=>c*vsr),
        ust=[pv[1][0]-usr[0],pv[1][1]-usr[1],pv[1][2]-usr[2]], vst=z3Pm(ust),
        betsr=vsr/Z3_DC, betst=vst/Z3_DC;
  let bett=betst, betr=betsr, d=1, del=0, od=0, odel=0, odd=0, oddel=0, i;
  for(i=0;i<IMAX;i++){
    d=1+betr; const ww=betr*betr+bett*bett;
    del=-ww/(Math.sqrt(1-ww)+1);
    betr=d*betsr+del; bett=d*betst;
    if(i>0){ const dd=Math.abs(d-od), ddel=Math.abs(del-odel);
      if(i>1&&dd>=odd&&ddel>=oddel) break;
      odd=dd; oddel=ddel; }
    od=d; odel=del; }
  if(i>=IMAX) iwarn+=4;
  /* THE ONE PLACE THIS DEPARTS FROM THE C SOURCE, AND WHY. ERFA writes the inertial
     radial velocity as (d + δ/β_r)·v_sr·x̂ with a guard "β_r ≠ 0 ? … : 1" against
     0/0. Algebraically that is (d·v_sr + δ·c)·x̂, and the guard gets the LIMIT wrong:
     at an observed radial velocity of exactly zero the inertial one is δ·c — the
     transverse Doppler term, −3.4 m/s for a star moving 100 mas/yr at 90 pc — and the
     guard sets it to 0. The C library only returns the right number because rounding
     leaves v_sr ≈ 1e-20 instead of 0; a JavaScript build of the same code lands on the
     exact zero and was measured 25 mas away from ERFA after 100 000 years. The
     continuous form is the same expression wherever the original is defined, and the
     right one where it is not. */
  const vr=d*vsr+del*Z3_DC;
  pv[1]=[vr*x[0]+d*ust[0], vr*x[1]+d*ust[1], vr*x[2]+d*ust[2]];
  return {pv,iwarn}; }

function z3Pvstar(pv){
  const pr=z3Pm(pv[0]), x=pv[0].map(c=>c/pr), vr=z3Pdp(x,pv[1]),
        ur=x.map(c=>c*vr), ut=[pv[1][0]-ur[0],pv[1][1]-ur[1],pv[1][2]-ur[2]],
        bett=z3Pm(ut)/Z3_DC, betr=vr/Z3_DC, d=1+betr, w=betr*betr+bett*bett;
  if(d===0||w>=1) return null;
  const del=-w/(Math.sqrt(1-w)+1), k=Z3_DC*(betr-del)/d;
  const obs=[pv[0],[ut[0]/d+k*x[0], ut[1]/d+k*x[1], ut[2]/d+k*x[2]]];
  const s=z3Pv2s(obs); if(s.r===0) return null;
  let a=s.th%(2*Math.PI); if(a<0) a+=2*Math.PI;
  return {ra:a, dec:s.ph, pmr:s.td*Z3_DJY, pmd:s.pd*Z3_DJY, px:Z3_DR2AS/s.r,
          rv:1e-3*s.rd*Z3_DAU/Z3_DAYSEC, pv:obs}; }

function z3Starpm(ra1,dec1,pmr1,pmd1,px1,rv1,ep1,ep2){
  const {pv:pv1}=z3Starpv(ra1,dec1,pmr1,pmd1,px1,rv1);
  const tl1=z3Pm(pv1[0])/Z3_DC, dt=(ep2-ep1)*Z3_DJY;
  const g=[pv1[0][0]+(dt+tl1)*pv1[1][0], pv1[0][1]+(dt+tl1)*pv1[1][1], pv1[0][2]+(dt+tl1)*pv1[1][2]];
  const r2=z3Pdp(g,g), rdv=z3Pdp(g,pv1[1]), v2=z3Pdp(pv1[1],pv1[1]), c2mv2=Z3_DC*Z3_DC-v2;
  if(c2mv2<=0) return null;
  const tl2=(-rdv+Math.sqrt(rdv*rdv+c2mv2*r2))/c2mv2, k=dt+(tl1-tl2);
  const pv2=[[pv1[0][0]+k*pv1[1][0], pv1[0][1]+k*pv1[1][1], pv1[0][2]+k*pv1[1][2]], pv1[1]];
  const out=z3Pvstar(pv2); if(!out) return null;
  out.lightTimeYears=tl2/Z3_DJY; out.positionAU=pv2[0]; return out; }

const ZOD3D_ZODIAC=['Ari','Tau','Gem','Cnc','Leo','Vir','Lib','Sco','Sgr','Cap','Aqr','Psc'];

const ZOD3D_ORDER=[...ZOD3D_ZODIAC,'Oph'];

const ZOD3D_PC_AU=648000/Math.PI;

const ZOD3D_KAPPA_PER_MYR=0.0378;

const ZOD3D_DOMAIN_YR=1e6;

const zod3dTideError=years=>0.5*Math.pow(ZOD3D_KAPPA_PER_MYR*Math.abs(years)/1e6,2);

const ZOD3D=ZOD3D_STARS.map((r,i)=>{ const o={i}; ZOD3D_FIELDS.forEach((f,k)=>o[f]=r[k]); return o; });

const zod3dOpen=s=>!!s.spanLo&&s.spanHi===null;

const zod3dPlacedPlx=s=>{ if(!(s.plx>0)||s.q==='D') return null;
  if(zod3dOpen(s)) return 1000/s.spanLo;
  return s.plx; };

function zod3dState(s,epJ){
  if(Math.abs(epJ-2000)>2000){ const a=zod3dStateLinear(s,2000), b=a&&zod3dStateLinear(s,2001); if(!a||!b) return null;
    if(!s._ride){ const pc=ZOD3D_PC_AU; s._ride={p:a.posAU.map(x=>x/pc), v:a.posAU.map((x,i)=>(b.posAU[i]-x)/pc*1e6/GAL_RIDE.KMS)}; }
    const e=galRideEq(s._ride.p,s._ride.v,epJ,null), r=Math.hypot(e[0],e[1],e[2]);
    return {...a, raDeg:((Math.atan2(e[1],e[0])*180/Math.PI)+360)%360, decDeg:Math.asin(e[2]/r)*180/Math.PI, distPc:r, plxMas:1000/r, posAU:e.map(x=>x*ZOD3D_PC_AU), rideGalaxy:true}; }
  return zod3dStateLinear(s,epJ); }

function zod3dStateLinear(s,epJ){
  const plx=zod3dPlacedPlx(s); if(plx==null) return null;
  const de=s.de*Math.PI/180;
  const r=z3Starpm(s.ra*Math.PI/180, de, (s.pmra/3.6e6)*Math.PI/180/Math.cos(de),
                   (s.pmde/3.6e6)*Math.PI/180, plx/1000, s.rv||0, s.ep, epJ);
  if(!r) return null;
  return {raDeg:r.ra*180/Math.PI, decDeg:r.dec*180/Math.PI, plxMas:r.px*1000, distPc:1/r.px,
    rvKmS:r.rv, pmRaMasYr:r.pmr*Math.cos(r.dec)*180/Math.PI*3.6e6, pmDecMasYr:r.pmd*180/Math.PI*3.6e6,
    lightTimeYr:r.lightTimeYears, posAU:r.positionAU}; }

function zod3dDepth(con,epJ){
  const hips=new Set((ZOD3D_FIGURES[con]||[]).flat());
  const P=[]; for(const s of ZOD3D){ if(s.con!==con||!hips.has(s.hip)) continue;
    if(zod3dOpen(s)) continue;                               /* a lower bound is not a depth */
    const st=zod3dState(s,epJ); if(st) P.push({s,st,p:st.posAU}); }
  if(P.length<2) return null;
  const c=[0,1,2].map(k=>P.reduce((t,q)=>t+q.p[k],0)/P.length), cl=Math.hypot(c[0],c[1],c[2]), u=c.map(x=>x/cl);
  let tr=0; for(const q of P){ const a=q.p[0]*u[0]+q.p[1]*u[1]+q.p[2]*u[2];
    tr=Math.max(tr,Math.hypot(q.p[0]-a*u[0],q.p[1]-a*u[1],q.p[2]-a*u[2])); }
  const ds=P.map(q=>q.st.distPc), lo=Math.min(...ds), hi=Math.max(...ds);
  const near=P.find(q=>q.st.distPc===lo).s, far=P.find(q=>q.st.distPc===hi).s;
  return {stars:P.length, nearPc:lo, farPc:hi, near, far,
    radialPc:hi-lo, transversePc:2*tr/ZOD3D_PC_AU, ratio:(hi-lo)/(2*tr/ZOD3D_PC_AU)}; }

const STAT_MG=[[-0.0548755604,-0.8734370902,-0.4838350155],[0.4941094279,-0.4448296300,0.7469822445],[-0.8676661490,-0.1980763734,0.4559837762]];

const statToGal=v=>STAT_MG.map(r=>r[0]*v[0]+r[1]*v[1]+r[2]*v[2]);

const WIND_C=2.99792458e8;

const WIND_G=6.67430e-11;

const WIND_MSUN=1.98892e30;

const WIND_RSUN=6.957e8;

const WIND_LSUN=3.828e26;

const WIND_YR=3.15576e7;

const windMomentumCeiling=(Lsun,vinf)=>(vinf>0)?Lsun*WIND_LSUN/(WIND_C*vinf):Infinity;

const windCeilingMsunYr=(Lsun,vinf)=>windMomentumCeiling(Lsun,vinf)*WIND_YR/WIND_MSUN;

const WIND_VINF_OVER_VESC=2.6;

const windEscapeSpeed=(m,r)=>Math.sqrt(2*WIND_G*m*WIND_MSUN/(Math.max(1e-9,r)*WIND_RSUN));

const windTerminalSpeed=(m,r)=>WIND_VINF_OVER_VESC*windEscapeSpeed(m,r);

const windFractionLost=(f,eps,fcore,vinf)=>(vinf>0)?f*eps*fcore*WIND_C/vinf:Infinity;

const SEIS_DNU_SUN=135.1;

const SEIS_NUMAX_SUN=3090;

const SEIS_TEFF_SUN=5777;

const SEIS_LOGG_SUN=4.43812;

const SEIS_RHO_SUN=1410.1;

const seisRadius=(dnu,numax,teff)=>(numax/SEIS_NUMAX_SUN)*Math.pow(dnu/SEIS_DNU_SUN,-2)*Math.sqrt(Math.max(1e-9,teff)/SEIS_TEFF_SUN);

const seisMass=(dnu,numax,teff)=>Math.pow(numax/SEIS_NUMAX_SUN,3)*Math.pow(dnu/SEIS_DNU_SUN,-4)*Math.pow(Math.max(1e-9,teff)/SEIS_TEFF_SUN,1.5);

const seisDensitySolar=dnu=>Math.pow(dnu/SEIS_DNU_SUN,2);

const seisDensity=dnu=>seisDensitySolar(dnu)*SEIS_RHO_SUN;

const seisLogg=(numax,teff)=>SEIS_LOGG_SUN+Math.log10((numax/SEIS_NUMAX_SUN)*Math.sqrt(Math.max(1e-9,teff)/SEIS_TEFF_SUN));

const HR_MSUN=1.98892e30;

const HR_LSUN=3.828e26;

const HR_TSUN=5772;

const HR_C=299792458;

const HR_G=6.67430e-11;

const HR_YR=3.155693e7;

const HR_GYR=1e9*HR_YR;

const HR_EPS=0.007;

const HR_FCORE=0.1;

const HR_KAPPA=0.034;

const hrEddington=m=>4*Math.PI*HR_G*m*HR_MSUN*HR_C/HR_KAPPA/HR_LSUN;

const HR_EDD_FRACTION=0.833;

function hrLuminosity(m){
  if(!(m>0)) return 0;
  if(m<0.43) return 0.23*Math.pow(m,2.3);
  if(m<2)    return Math.pow(m,4);
  if(m<55)   return 1.4*Math.pow(m,3.5);
  return HR_EDD_FRACTION*hrEddington(m);
}

function hrExponent(m){
  const h=1e-4;
  const a=hrLuminosity(m*(1-h)), b=hrLuminosity(m*(1+h));
  if(!(a>0&&b>0)) return NaN;
  return (Math.log(b)-Math.log(a))/(Math.log(m*(1+h))-Math.log(m*(1-h)));
}

function hrRadius(m){ return (m<1)?Math.pow(m,0.8):Math.pow(m,0.57); }

function hrTemperature(m){
  const R=hrRadius(m);
  return HR_TSUN*Math.pow(hrLuminosity(m)/(R*R),0.25);
}

function hrLifetime(m){
  const L=hrLuminosity(m);
  if(!(L>0)) return Infinity;
  return HR_EPS*HR_FCORE*m*HR_MSUN*HR_C*HR_C/(L*HR_LSUN);
}

const hrLifetimeGyr=m=>hrLifetime(m)/HR_GYR;

function hrTurnoff(ageGyr){
  if(!(ageGyr>0)) return 200;
  let lo=0.05, hi=200;
  for(let i=0;i<200;i++){
    const mid=Math.sqrt(lo*hi);
    if(hrLifetimeGyr(mid)>ageGyr) lo=mid; else hi=mid;
  }
  return Math.sqrt(lo*hi);
}

function hrRemnant(m){
  if(m<8) return 0.109*m+0.394;
  if(m<25) return 1.4;
  return 0.1*m;
}

function hrIMF(m,kind){
  if(kind==='kroupa'){
    if(m<0.08) return 0;
    if(m<0.5)  return Math.pow(m/0.5,-1.3)*Math.pow(0.5,-2.3);
    return Math.pow(m,-2.3);
  }
  return Math.pow(m,-2.35);
}

function hrMassToLight(ageGyr,opt){
  const o=opt||{};
  const kind=o.imf||'salpeter';
  const lo=(o.m_min==null?0.1:o.m_min);
  const hi=(o.m_max==null?100:o.m_max);
  const N=(o.samples==null?4000:Math.round(o.samples));
  const mto=hrTurnoff(ageGyr);
  let mass=0, light=0, massAlive=0, nAlive=0, nDead=0;
  const dx=(Math.log(hi)-Math.log(lo))/N;
  for(let i=0;i<N;i++){
    const x=Math.log(lo)+dx*(i+0.5);
    const m=Math.exp(x);
    const w=hrIMF(m,kind)*m*dx;
    if(m<=mto){ mass+=w*m; massAlive+=w*m; light+=w*hrLuminosity(m); nAlive+=w; }
    else { mass+=w*hrRemnant(m); nDead+=w; }
  }
  return {mass_to_light:(light>0)?mass/light:Infinity,
    turnoff:mto, mass_total:mass, light_total:light,
    mass_in_living_stars:massAlive, remnant_mass_fraction:(mass>0)?(mass-massAlive)/mass:0,
    number_alive:nAlive, number_dead:nDead};
}

function hrMassToLightNoRemnants(ageGyr,opt){
  const r=hrMassToLight(ageGyr,opt);
  return (r.light_total>0)?r.mass_in_living_stars/r.light_total:Infinity;
}

function hrGiantLight(ageGyr,windowFraction,brightening,opt){
  const o=opt||{};
  const kind=o.imf||'salpeter';
  const lo=(o.m_min==null?0.1:o.m_min);
  const hi=(o.m_max==null?100:o.m_max);
  const N=(o.samples==null?4000:Math.round(o.samples));
  const mto=hrTurnoff(ageGyr);
  const dx=(Math.log(hi)-Math.log(lo))/N;
  let msLight=0;
  for(let i=0;i<N;i++){
    const m=Math.exp(Math.log(lo)+dx*(i+0.5));
    if(m<=mto) msLight+=hrIMF(m,kind)*m*dx*hrLuminosity(m);
  }
  const w=(windowFraction||0)*hrLifetimeGyr(mto);
  if(!(w>0)||!(brightening>0)) return {ms_light:msLight, giant_light:0, ratio:0, mass_window_top:mto};
  const mHi=hrTurnoff(Math.max(1e-9,ageGyr-w));
  let nG=0;
  for(let i=0;i<N;i++){
    const m=Math.exp(Math.log(lo)+dx*(i+0.5));
    if(m>mto&&m<=mHi) nG+=hrIMF(m,kind)*m*dx;
  }
  const gl=nG*brightening*hrLuminosity(mto);
  return {ms_light:msLight, giant_light:gl, ratio:(msLight>0)?gl/msLight:Infinity,
    mass_window_top:mHi, number_of_giants:nG, window_gyr:w};
}

const GR_G=6.67430e-11;

const GR_MSUN=1.98892e30;

const GR_KPC=3.0856775814913673e19;

const GR_C=299792458;

const GR_MPC=3.0856775814913673e22;

const GR_HELIUM=1.33;

function grBessI0(x){
  const a=Math.abs(x);
  if(a<3.75){ const y=(x/3.75)*(x/3.75);
    return 1+y*(3.5156229+y*(3.0899424+y*(1.2067492+y*(0.2659732+y*(0.360768e-1+y*0.45813e-2))))); }
  const y=3.75/a;
  return Math.exp(a)/Math.sqrt(a)*(0.39894228+y*(0.1328592e-1+y*(0.225319e-2+y*(-0.157565e-2
    +y*(0.916281e-2+y*(-0.2057706e-1+y*(0.2635537e-1+y*(-0.1647633e-1+y*0.392377e-2))))))));
}

function grBessI1(x){
  const a=Math.abs(x);
  let ans;
  if(a<3.75){ const y=(x/3.75)*(x/3.75);
    ans=a*(0.5+y*(0.87890594+y*(0.51498869+y*(0.15084934+y*(0.2658733e-1+y*(0.301532e-2+y*0.32411e-3)))))); }
  else { const y=3.75/a;
    let t=0.2282967e-1+y*(-0.2895312e-1+y*(0.1787654e-1-y*0.420059e-2));
    t=0.39894228+y*(-0.3988024e-1+y*(-0.362018e-2+y*(0.163801e-2+y*(-0.1031555e-1+y*t))));
    ans=t*Math.exp(a)/Math.sqrt(a); }
  return x<0?-ans:ans;
}

function grBessK0(x){
  if(x<=2){ const y=x*x/4;
    return -Math.log(x/2)*grBessI0(x)+(-0.57721566+y*(0.42278420+y*(0.23069756+y*(0.3488590e-1
      +y*(0.262698e-2+y*(0.10750e-3+y*0.74e-5)))))); }
  const y=2/x;
  return Math.exp(-x)/Math.sqrt(x)*(1.25331414+y*(-0.7832358e-1+y*(0.2189568e-1+y*(-0.1062446e-1
    +y*(0.587872e-2+y*(-0.251540e-2+y*0.53208e-3))))));
}

function grBessK1(x){
  if(x<=2){ const y=x*x/4;
    return Math.log(x/2)*grBessI1(x)+(1/x)*(1+y*(0.15443144+y*(-0.67278579+y*(-0.18156897
      +y*(-0.1919402e-1+y*(-0.110404e-2+y*(-0.4686e-4))))))); }
  const y=2/x;
  return Math.exp(-x)/Math.sqrt(x)*(1.25331414+y*(0.23498619+y*(-0.3655620e-1+y*(0.1504268e-1
    +y*(-0.780353e-2+y*(0.325614e-2+y*(-0.68245e-3)))))));
}

function grDiscV2(r,S0,Rd){
  const y=r/(2*Rd);
  if(!(y>1e-9)) return 0;
  return 4*Math.PI*GR_G*S0*Rd*y*y*(grBessI0(y)*grBessK0(y)-grBessI1(y)*grBessK1(y));
}

const grDiscSigma0=(Md,Rd)=>Md/(2*Math.PI*Rd*Rd);

const grDiscV=(r,S0,Rd)=>Math.sqrt(Math.max(0,grDiscV2(r,S0,Rd)));

function grDiscPeak(S0,Rd){
  let lo=0.05*Rd, hi=8*Rd;
  const phi=(Math.sqrt(5)-1)/2;
  let a=hi-phi*(hi-lo), b=lo+phi*(hi-lo);
  for(let i=0;i<200;i++){
    if(grDiscV2(a,S0,Rd)>grDiscV2(b,S0,Rd)){ hi=b; b=a; a=hi-phi*(hi-lo); }
    else { lo=a; a=b; b=lo+phi*(hi-lo); }
  }
  const r=0.5*(lo+hi);
  return {radius:r, radius_over_Rd:r/Rd, speed:Math.sqrt(Math.max(0,grDiscV2(r,S0,Rd)))};
}

function grGasV2(r,Mg,Rg){ return grDiscV2(r,grDiscSigma0(Mg,Rg),Rg); }

function grNFWMass(r,rhos,rs){
  const x=r/rs;
  return 4*Math.PI*rhos*rs*rs*rs*(Math.log(1+x)-x/(1+x));
}

function grNFWV(r,rhos,rs){ return Math.sqrt(GR_G*grNFWMass(r,rhos,rs)/r); }

function grIsoV(r,rho0,rc){
  if(!(r>0)) return 0;
  return Math.sqrt(4*Math.PI*GR_G*rho0*rc*rc*(1-(rc/r)*Math.atan(r/rc)));
}

