function nbgRot(th){ const c=Math.cos(th), s=Math.sin(th); return [[c,0,-s,0],[0,1,0,0],[s,0,c,0],[0,0,0,1]]; }

function nbgMv(M,v){ return [0,1,2,3].map(i=>M[i][0]*v[0]+M[i][1]*v[1]+M[i][2]*v[2]+M[i][3]*v[3]); }

function nbgMtv(M,v){ return [0,1,2,3].map(i=>M[0][i]*v[0]+M[1][i]*v[1]+M[2][i]*v[2]+M[3][i]*v[3]); }

