function nbgCross4(x,u,v){ const Fr=gmodeFrame(x), cu=Fr.map(f=>f[0]*u[0]+f[1]*u[1]+f[2]*u[2]+f[3]*u[3]), cv=Fr.map(f=>f[0]*v[0]+f[1]*v[1]+f[2]*v[2]+f[3]*v[3]);
  const c=[cu[1]*cv[2]-cu[2]*cv[1], cu[2]*cv[0]-cu[0]*cv[2], cu[0]*cv[1]-cu[1]*cv[0]]; return [0,1,2,3].map(i=>c[0]*Fr[0][i]+c[1]*Fr[1][i]+c[2]*Fr[2][i]); }

function nbgPoynting(R,x,eps,th){ const F=nbgFieldEB(R,x,eps,th), S=nbgCross4(x,F.E,F.B), n=Math.hypot(...S); return n>1e-300?S.map(v=>v/n):null; }

function nbgOptics(R,x,eps,th,h){ h=h||1e-5; const V=y=>nbgPoynting(R,y,eps,th), v=V(x); if(!v) return null; const Fr=gmodeFrame(x), dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2]+a[3]*b[3];
  const tang=w=>{ const k=dot(w,x); return w.map((c,i)=>c-k*x[i]); }, Dd=e=>{ const p=V(x.map((c,i)=>c+h*e[i])), m=V(x.map((c,i)=>c-h*e[i])); return tang(p.map((c,i)=>(c-m[i])/(2*h))); };
  /* an orthonormal pair e₁, e₂ ⊥ V in T_xS³ */
  let a=Fr.map(f=>dot(f,v)), j=Math.abs(a[0])<0.8?0:1; let e1=Fr[j].map((c,i)=>c-dot(Fr[j],v)*v[i]); const n1=Math.hypot(...e1); e1=e1.map(c=>c/n1); const e2=nbgCross4(x,v,e1);
  const DV=Dd(v), D1=Dd(e1), D2=Dd(e2), A11=dot(D1,e1), A12=dot(D1,e2), A21=dot(D2,e1), A22=dot(D2,e2);
  return {geodesic:Math.hypot(...DV), expansion:(A11+A22)/2, twist:(A12-A21)/2, shear:Math.hypot((A11-A22)/2,(A12+A21)/2), divV:A11+A22, V:v}; }

function nbgCheck(R,opt){ opt=opt||{}; const m=nbgDegree(R), rnd=gmodeRng(opt.seed||17), eps=opt.eps||0, th=opt.th; let eig=0, div=0, nul=0, eq=0, geo=0, sh=0, tw=0, divV=0, kap=0, n=0, k=0;
  for(let s=0;s<(opt.samples||14);s++){ const x=gmodeRandS3(rnd), F=nbgFieldEB(R,x,eps,th), E=F.E, B=F.B, e2=E[0]*E[0]+E[1]*E[1]+E[2]*E[2]+E[3]*E[3], b2=B[0]*B[0]+B[1]*B[1]+B[2]*B[2]+B[3]*B[3];
    if(e2<1e-8) continue;
    for(const part of ['E','B']){ const Vf=y=>nbgFieldEB(R,y,eps,th)[part], v=part==='E'?E:B, C=gmodeCurlAt(Vf,x,1e-5), vv=part==='E'?e2:b2; if(vv<1e-10) continue;
      kap+=(C.curl[0]*v[0]+C.curl[1]*v[1]+C.curl[2]*v[2]+C.curl[3]*v[3])/vv; k++; eig=Math.max(eig,Math.hypot(...C.curl.map((c,i)=>c-(m+2)*v[i]))/Math.sqrt(vv)/(m+2)); div=Math.max(div,Math.abs(C.div)/Math.sqrt(vv)); }
    nul=Math.max(nul,Math.abs(E[0]*B[0]+E[1]*B[1]+E[2]*B[2]+E[3]*B[3])/e2); eq=Math.max(eq,Math.abs(e2-b2)/e2);
    const O=nbgOptics(R,x,eps,th); if(!O) continue; n++; geo=Math.max(geo,O.geodesic); sh=Math.max(sh,O.shear); tw+=Math.abs(O.twist);
    const h=1e-5, rho=y=>{ const G=nbgFieldEB(R,y,eps,th); return 0.5*Math.log(G.E[0]*G.E[0]+G.E[1]*G.E[1]+G.E[2]*G.E[2]+G.E[3]*G.E[3]); }, vr=(rho(x.map((c,i)=>c+h*O.V[i]))-rho(x.map((c,i)=>c-h*O.V[i])))/(2*h);
    divV=Math.max(divV,Math.abs(O.divV+2*vr)); }
  return {m, lambda:m+2, kappa:k?kap/k:NaN, eigResidual:eig, divResidual:div, nullDot:nul, normDiff:eq, geodesic:geo, shear:sh, twist:n?tw/n:NaN, divVIdentity:divV, samples:n, eps}; }

function nbgFibre(r,s){ const w=r.w; if(!w) return [Math.cos(s),Math.sin(s),0,0]; const n=Math.sqrt(1+w[0]*w[0]+w[1]*w[1]), z2=[Math.cos(s)/n,Math.sin(s)/n], z1=nbgCm(w,z2); return [z1[0],z1[1],z2[0],z2[1]]; }

function nbgPsiInv(t,y){ const a=y[0], b=y[1], c=y[2], d=y[3], s=2*(1-t*b)/(1-a); return [(c*s-2*t*d)/2, -(d*s+2*t*c)/2, (b*s+2*t*a)/2]; }

function nbgCircle(r,t){ if(!r.w) return {line:true, centre:[0,0,0], radius:Infinity, normal:[0,0,1]}; const u=r.w[0], v=r.w[1], n=Math.hypot(-v,u,1); return {line:false, centre:[u,v,0], radius:Math.sqrt(1+u*u+v*v+t*t), normal:[-v/n,u/n,1/n]}; }

function nbgCirclePts(r,t,n){ const out=[]; n=n||128; for(let i=0;i<n;i++){ const s=NBG_TAU*i/n, y=nbgFibre(r,s); if(1-y[0]<1e-9) continue; out.push(nbgPsiInv(t,y)); } return out; }

function nbgGaussLink(P,Q){ let s=0; const nP=P.length, nQ=Q.length;
  for(let i=0;i<nP;i++){ const a=P[i], b=P[(i+1)%nP], da=[b[0]-a[0],b[1]-a[1],b[2]-a[2]], ma=[(a[0]+b[0])/2,(a[1]+b[1])/2,(a[2]+b[2])/2];
    for(let j=0;j<nQ;j++){ const c=Q[j], d=Q[(j+1)%nQ], db=[d[0]-c[0],d[1]-c[1],d[2]-c[2]], mb=[(c[0]+d[0])/2,(c[1]+d[1])/2,(c[2]+d[2])/2], r=[ma[0]-mb[0],ma[1]-mb[1],ma[2]-mb[2]], rl=Math.hypot(r[0],r[1],r[2]);
      s+=(r[0]*(da[1]*db[2]-da[2]*db[1])+r[1]*(da[2]*db[0]-da[0]*db[2])+r[2]*(da[0]*db[1]-da[1]*db[0]))/(rl*rl*rl); } }
  return s/(4*Math.PI); }

function nbgTwistorDim(m){ const n=2-m; let cech=0; for(let j=-4*m-8;j<=4*m+8;j++) if(!(j>=0)&&!(j<=n)) cech++;
  const h0=Math.max(0,n+1), rr=h0-(n+1); return {m, base:cech, baseRR:rr, sym:m+1, dim:(m+1)*cech, closed:m>=4?(m+1)*(m-3):0, sValues:Array.from({length:cech},(_,i)=>i+1)}; }

function nbgHam(H,lam,c,w){ const m=H.k.length-1, ls=[1,0]; let L=[1,0]; for(let i=0;i<H.s;i++) L=nbgCd(L,lam); let hc=[0,0], hw=[0,0], h=[0,0];
  const pw=(z,e)=>{ let r=[1,0]; for(let i=0;i<e;i++) r=nbgCm(r,z); return r; };
  for(let a=0;a<=m;a++){ const k=H.k[a]; if(!k||(!k[0]&&!k[1])) continue; const b=m-a, ca=pw(c,a), wb=pw(w,b), kl=nbgCm(k,L);
    h=h.map((v,i)=>v+nbgCm(kl,nbgCm(ca,wb))[i]); if(a>0){ const t=nbgCm(nbgCm(kl,[a,0]),nbgCm(pw(c,a-1),wb)); hc=[hc[0]+t[0],hc[1]+t[1]]; } if(b>0){ const t=nbgCm(nbgCm(kl,[b,0]),nbgCm(ca,pw(w,b-1))); hw=[hw[0]+t[0],hw[1]+t[1]]; } }
  void ls; return {h, dc:[-hw[0],-hw[1]], dw:hc}; }

function nbgFlow(H,lam,c,w,eps,steps){ steps=steps||24; const dt=eps/steps; let C=c.slice(), W=w.slice();
  const f=(C,W)=>{ const X=nbgHam(H,lam,C,W); return [X.dc,X.dw]; }, ax=(a,b,k)=>[a[0]+k*b[0],a[1]+k*b[1]];
  for(let i=0;i<steps;i++){ const k1=f(C,W), k2=f(ax(C,k1[0],dt/2),ax(W,k1[1],dt/2)), k3=f(ax(C,k2[0],dt/2),ax(W,k2[1],dt/2)), k4=f(ax(C,k3[0],dt),ax(W,k3[1],dt));
    C=[0,1].map(j=>C[j]+dt/6*(k1[0][j]+2*k2[0][j]+2*k3[0][j]+k4[0][j])); W=[0,1].map(j=>W[j]+dt/6*(k1[1][j]+2*k2[1][j]+2*k3[1][j]+k4[1][j])); }
  return {c:C, w:W, h:nbgHam(H,lam,C,W).h}; }

function nbgFlowJacobian(H,lam,c,w,eps){ const d=1e-6, F=(C,W)=>nbgFlow(H,lam,C,W,eps), a=F([c[0]+d,c[1]],w), b=F([c[0]-d,c[1]],w), e=F(c,[w[0]+d,w[1]]), g=F(c,[w[0]-d,w[1]]);
  const dcc=[(a.c[0]-b.c[0])/(2*d),(a.c[1]-b.c[1])/(2*d)], dwc=[(a.w[0]-b.w[0])/(2*d),(a.w[1]-b.w[1])/(2*d)], dcw=[(e.c[0]-g.c[0])/(2*d),(e.c[1]-g.c[1])/(2*d)], dww=[(e.w[0]-g.w[0])/(2*d),(e.w[1]-g.w[1])/(2*d)];
  const det=nbgCm(dcc,dww).map((v,i)=>v-nbgCm(dcw,dwc)[i]); return {det, residual:Math.hypot(det[0]-1,det[1]), hDrift:(()=>{ const h0=nbgHam(H,lam,c,w).h, h1=F(c,w).h; return Math.hypot(h1[0]-h0[0],h1[1]-h0[1])/(Math.hypot(h0[0],h0[1])+1e-300); })()}; }

