function hgpGcd(a,b){ if(a<0n) a=-a; if(b<0n) b=-b; while(b){ const t=a%b; a=b; b=t; } return a; }

function hgpQ(n,d){ n=BigInt(n); d=d==null?1n:BigInt(d); if(d<0n){ n=-n; d=-d; } const g=hgpGcd(n,d)||1n; return [n/g,d/g]; }

const hgpAdd=(x,y)=>hgpQ(x[0]*y[1]+y[0]*x[1],x[1]*y[1]), hgpSub=(x,y)=>hgpQ(x[0]*y[1]-y[0]*x[1],x[1]*y[1]);

