const hgpCmp=(x,y)=>{ const l=x[0]*y[1], r=y[0]*x[1]; return l<r?-1:l>r?1:0; };

const hgpLt=(x,y)=>hgpCmp(x,y)<0, hgpLe=(x,y)=>hgpCmp(x,y)<=0;

