function pxTransferValue(T){ const full=T.K-1; let tot=0n; for(const P of T.cur) if(P&&P.has(full)) tot+=P.get(full); return tot; }

function pxMomentByTransfer(n,k){ if(n===0) return 0n; const T=pxTransferStart(n,k); while(!pxTransferStep(T)){} return pxTransferValue(T); }

function pxDen(m){ let den=[1n]; for(let r=0;r<=m;r++){ const nd=Array(den.length+2).fill(0n); den.forEach((c,i)=>{ nd[i]+=c; nd[i+1]-=c; nd[i+2]-=c; }); den=nd; } return den; }

function pxSeries(P,m,N){ const den=pxDen(m), s=[]; for(let k=0;k<=N;k++){ let v=k<P.length?P[k]:0n; for(let i=1;i<den.length&&i<=k;i++) v-=den[i]*s[k-i]; s.push(v); } return s; }

