function htTcrit(eta,zeta,h){ h=h||1; const C=1-eta, disc=C*C-4*zeta, X=(4*zeta/eta-C)/Math.sqrt(disc); return X>=1?Math.acosh(X)/(2*h):0; }

const ymLevel=l=>({gauge:l+1, gaugeDeg:2*l*(l+2), scalar:Math.sqrt(l*(l+2)), scalarDeg:(l+1)*(l+1), claimDeg:2*(l+1)*(l+1)});

const GS_PHI=(1+Math.sqrt(5))/2;

function gsG(x){ return (Math.PI-x)/Math.tan(x)/(4*Math.PI*Math.PI); }

function gsGamma(x){ return (x-Math.sin(x)*Math.cos(x))/Math.PI; }

function gsFlux(x){ return 1-gsGamma(x); }

function gsHierNet(D){ return 1/(1-Math.pow(GS_PHI,-D)); }

const VX_PHI=(1+Math.sqrt(5))/2;

function vxEnvelope(U){ let p=1; for(const x of U) p*=Math.sin(Math.min(Math.PI/2,Math.max(0,x)))**2; return p; }

function vxH(x){ const x2=x*x; return x2-x2*x2/3+2*x2*x2*x2/45; }

