let TRIAD_CENSUS=null;

function triadParse(t){ return String(t).split(',').map(x=>x.split(':').map(Number)); }

function triadPickCached(t){ if(!TRIAD_PICKS.has(t)) TRIAD_PICKS.set(t,triadPick(nsgBasisCached(3),triadParse(t))); return TRIAD_PICKS.get(t); }

function triadCensusCached(){ if(!TRIAD_CENSUS) TRIAD_CENSUS=s3TriadCensus(12); return TRIAD_CENSUS; }

function triadStart(mu,u){ const [lo,md,hi]=triadOrder(mu), a=[0,0,0]; if(mu[lo]===mu[md]||mu[md]===mu[hi]){ a[lo]=0.62; a[md]=0.5; a[hi]=0.6; const n=Math.hypot(...a); return a.map(x=>x/n); }
  const uu=Math.sign(u||1)*Math.max(1e-3,Math.min(0.97,Math.abs(u))), h=mu[md]+uu*(uu>0?mu[hi]-mu[md]:mu[md]-mu[lo]), x=(mu[hi]-h)/(mu[hi]-mu[lo]); a[lo]=Math.sqrt(Math.max(0,x)); a[hi]=Math.sqrt(Math.max(0,1-x)); return a; }

