function phaseItem(key){ if(key==='s3loop') return {key, prec:0.05, fam:'deep', P:(typeof S3!=='undefined'?S3.Circ:0)*1e9*365.2425*PHASE_DAY, kind:'model', t:['light round the cosmic S³','свет вокруг космической S³','Licht um die kosmische S³']}; return PHASE_CATALOGUE.find(x=>x.key===key)||null; }

