const POLE_W0=1;

function poleR(wr,wi,P){ const nr=wr-P.z[0], ni=wi-P.z[1], dr=wr-P.p[0], di=wi-P.p[1], D=dr*dr+di*di||1e-300;
  return [(nr*dr+ni*di)/D,(ni*dr-nr*di)/D]; }

const RPD_N=48, RPD_RCAR=2.7, RPD_RHMAX=1.9;

function rpdArea(p){ if(p<=0) return 0; if(p<0.4) return Math.pow(p/0.4,2); const q=(p-0.4)/0.6; return Math.pow(Math.max(0,1-q),4/3); }

function rpdRh(p){ return RPD_RHMAX*Math.sqrt(rpdArea(p)); }

const rpdLayer=i=>0.18+0.75*((i*0.6180339887)%1);

function rpdCounts(p){   // exact bookkeeping: swallowed set = horizon-history max (no un-swallowing);
  // during evaporation, hidden classes are RE-EXPRESSED one by one through the three channels.
  const rhPeak=rpdRh(Math.min(p,0.4)), sw=[];
  for(let i=0;i<RPD_N;i++){ if(rpdLayer(i)*RPD_RCAR < rhPeak) sw.push(i); }
  const q=p<=0.4?0:Math.min(1,(p-0.4)/0.6);
  const nRe=Math.min(sw.length,Math.floor(q*sw.length+1e-9));
  const reSet=sw.slice(0,nRe);   // deterministic order of re-expression
  return {swallowed:sw, reSet, acc:RPD_N-sw.length, hid:sw.length-nRe, re:nRe};
}

function rpdIext(p){ const c=rpdCounts(p); return Math.log2(Math.max(1,c.acc+c.re)); }

const HOL_TAU=2*Math.PI;

const holWrap=x=>Math.atan2(Math.sin(x),Math.cos(x));

const holPt=(theta,phi)=>[Math.sin(theta)*Math.cos(phi),Math.cos(theta),Math.sin(theta)*Math.sin(phi)];

function holTransportPure(theta,n){
  n=n||1024;
  const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
  const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
  const e0=[Math.cos(theta),-Math.sin(theta),0], f0=[0,0,1];
  let v=e0.slice(), p=holPt(theta,0);
  for(let i=1;i<=n;i++){
    const q=holPt(theta,HOL_TAU*i/n), ax=cross(p,q), sn=Math.hypot(ax[0],ax[1],ax[2]);
    if(sn>1e-15){ const k=[ax[0]/sn,ax[1]/sn,ax[2]/sn], a=Math.atan2(sn,Math.max(-1,Math.min(1,dot(p,q)))), c=Math.cos(a), s=Math.sin(a), kv=cross(k,v), kd=dot(k,v)*(1-c);
      v=[v[0]*c+kv[0]*s+k[0]*kd, v[1]*c+kv[1]*s+k[1]*kd, v[2]*c+kv[2]*s+k[2]*kd]; }
    p=q;
  }
  return {angle:Math.atan2(dot(v,f0),dot(v,e0)), vector:v, steps:n};
}

function holBerryWilson(theta,gauge=0,n=257){
  const c2=Math.cos(theta/2)**2,s2=Math.sin(theta/2)**2,chi=p=>gauge*(Math.sin(3*p+.2)+.37*Math.cos(5*p-.4));
  let pr=1,pi=0,minOverlap=1,rawLogMod=0;
  for(let i=0;i<n;i++){
    const p=HOL_TAU*i/n,q=HOL_TAU*((i+1)%n)/n,dp=q-p,dg=chi(q)-chi(p);
    const br=c2+s2*Math.cos(dp),bi=s2*Math.sin(dp),cg=Math.cos(dg),sg=Math.sin(dg);
    const zr=br*cg-bi*sg,zi=br*sg+bi*cg,m=Math.hypot(zr,zi);minOverlap=Math.min(minOverlap,m);rawLogMod+=Math.log(Math.max(m,1e-300));
    const nr=zr/m,ni=zi/m,tr=pr*nr-pi*ni,ti=pr*ni+pi*nr;pr=tr;pi=ti;
  }
  return {phase:holWrap(-Math.atan2(pi,pr)),wilson:[pr,pi],min_overlap:minOverlap,raw_product_log_modulus:rawLogMod,vertices:n};
}

const holQ=(w=1,x=0,y=0,z=0)=>({w,x,y,z});

function holQMul(a,b){return holQ(a.w*b.w-a.x*b.x-a.y*b.y-a.z*b.z,a.w*b.x+a.x*b.w+a.y*b.z-a.z*b.y,a.w*b.y-a.x*b.z+a.y*b.w+a.z*b.x,a.w*b.z+a.x*b.y-a.y*b.x+a.z*b.w);}

function holQInv(q){const n=q.w*q.w+q.x*q.x+q.y*q.y+q.z*q.z;return holQ(q.w/n,-q.x/n,-q.y/n,-q.z/n);}

const holQNorm=q=>Math.hypot(q.w,q.x,q.y,q.z);

const holQAxis=(axis,a)=>axis==='x'?holQ(Math.cos(a/2),Math.sin(a/2),0,0):axis==='y'?holQ(Math.cos(a/2),0,Math.sin(a/2),0):holQ(Math.cos(a/2),0,0,Math.sin(a/2));

function holM3Mul(A,B){const C=new Array(9).fill(0);for(let r=0;r<3;r++)for(let c=0;c<3;c++)for(let k=0;k<3;k++)C[3*r+c]+=A[3*r+k]*B[3*k+c];return C;}

function holM3Vec(A,v){return [A[0]*v[0]+A[1]*v[1]+A[2]*v[2],A[3]*v[0]+A[4]*v[1]+A[5]*v[2],A[6]*v[0]+A[7]*v[1]+A[8]*v[2]];}

function holM3Det(A){return A[0]*(A[4]*A[8]-A[5]*A[7])-A[1]*(A[3]*A[8]-A[5]*A[6])+A[2]*(A[3]*A[7]-A[4]*A[6]);}

const holBoostX=a=>{const c=Math.cosh(a),s=Math.sinh(a);return [c,s,0,s,c,0,0,0,1];};

const holBoostY=a=>{const c=Math.cosh(a),s=Math.sinh(a);return [c,0,s,0,1,0,s,0,c];};

function holM2Mul(A,B){return [A[0]*B[0]+A[1]*B[2],A[0]*B[1]+A[1]*B[3],A[2]*B[0]+A[3]*B[2],A[2]*B[1]+A[3]*B[3]];}

const holM2Det=A=>A[0]*A[3]-A[1]*A[2];

function holM2Inv(A){const d=holM2Det(A);return [A[3]/d,-A[1]/d,-A[2]/d,A[0]/d];}

const actDot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);

const actNorm=a=>Math.hypot(...a);

const actScale=(a,s)=>a.map(v=>v*s);

const actJ=u=>[-u[1],u[0],-u[3],u[2]];

function actAlpha(u,v){return .5*(u[0]*v[1]-u[1]*v[0]+u[2]*v[3]-u[3]*v[2]);}

function actDAlpha(u,v){return u[0]*v[1]-u[1]*v[0]+u[2]*v[3]-u[3]*v[2];}

function actGauge(u,g){const c=Math.cos(g),s=Math.sin(g);return [c*u[0]-s*u[1],s*u[0]+c*u[1],c*u[2]-s*u[3],s*u[2]+c*u[3]];}

function actHopf(u){return [2*(u[0]*u[2]+u[1]*u[3]),2*(u[1]*u[2]-u[0]*u[3]),u[0]*u[0]+u[1]*u[1]-u[2]*u[2]-u[3]*u[3]];}

function actContactResidual(u){
  const R=actScale(actJ(u),2),e1=[-u[2],u[3],u[0],-u[1]],e2=[-u[3],-u[2],u[1],u[0]];
  return {norm:Math.abs(actDot(u,u)-1),alphaR:Math.abs(actAlpha(u,R)-1),contraction:Math.max(Math.abs(actDAlpha(R,e1)),Math.abs(actDAlpha(R,e2))),R,e1,e2};
}

function actGcd(a,b){a=Math.abs(a|0);b=Math.abs(b|0);while(b){const t=a%b;a=b;b=t;}return a||1;}

function actReebPath(eta,rel,N=512){const a=Math.cos(eta),b=Math.sin(eta),out=[];for(let i=0;i<=N;i++){const t=Math.PI*i/N,g=2*t;out.push([a*Math.cos(g),a*Math.sin(g),b*Math.cos(rel+g),b*Math.sin(rel+g)]);}return out;}

const nulC=(r=0,i=0)=>[r,i];

const nulCadd=(a,b)=>[a[0]+b[0],a[1]+b[1]];

const nulCsub=(a,b)=>[a[0]-b[0],a[1]-b[1]];

const nulCmul=(a,b)=>[a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]];

const nulCconj=a=>[a[0],-a[1]];

const nulCscale=(a,s)=>[a[0]*s,a[1]*s];

const nulCabs=a=>Math.hypot(a[0],a[1]);

function nulCdiv(a,b){const d=b[0]*b[0]+b[1]*b[1];return [(a[0]*b[0]+a[1]*b[1])/d,(a[1]*b[0]-a[0]*b[1])/d];}

function nulCMulExp(a,p){return nulCmul(a,[Math.cos(p),Math.sin(p)]);}

function nulMmul(A,B){return [[nulCadd(nulCmul(A[0][0],B[0][0]),nulCmul(A[0][1],B[1][0])),nulCadd(nulCmul(A[0][0],B[0][1]),nulCmul(A[0][1],B[1][1]))],[nulCadd(nulCmul(A[1][0],B[0][0]),nulCmul(A[1][1],B[1][0])),nulCadd(nulCmul(A[1][0],B[0][1]),nulCmul(A[1][1],B[1][1]))]];}

function nulMdag(A){return [[nulCconj(A[0][0]),nulCconj(A[1][0])],[nulCconj(A[0][1]),nulCconj(A[1][1])]];}

function nulMscale(A,s){return A.map(r=>r.map(z=>nulCscale(z,s)));}

function nulMdet(A){return nulCsub(nulCmul(A[0][0],A[1][1]),nulCmul(A[0][1],A[1][0]));}

function nulMouter(a,b){return [[nulCmul(a[0],nulCconj(b[0])),nulCmul(a[0],nulCconj(b[1]))],[nulCmul(a[1],nulCconj(b[0])),nulCmul(a[1],nulCconj(b[1]))]];}

function nulMatFromVec(x){return [[nulC(x[0]+x[3]),nulC(x[1],-x[2])],[nulC(x[1],x[2]),nulC(x[0]-x[3])]];}

function nulVecFromHermitian(M){return [(M[0][0][0]+M[1][1][0])/2,(M[0][1][0]+M[1][0][0])/2,(M[1][0][1]-M[0][1][1])/2,(M[0][0][0]-M[1][1][0])/2];}

const nulDot=(a,b)=>a[0]*b[0]-a[1]*b[1]-a[2]*b[2]-a[3]*b[3];

function nulSpinor(theta,phi,phase=0){return [nulC(Math.cos(theta/2)*Math.cos(phase),Math.cos(theta/2)*Math.sin(phase)),nulC(Math.sin(theta/2)*Math.cos(phase+phi),Math.sin(theta/2)*Math.sin(phase+phi))];}

function nulSpinNorm(s){return Math.sqrt(s.reduce((q,z)=>q+z[0]*z[0]+z[1]*z[1],0));}

function nulSpinDir(s){const q=nulCmul(nulCconj(s[0]),s[1]),a=s[0][0]**2+s[0][1]**2,b=s[1][0]**2+s[1][1]**2;return [a+b,2*q[0],2*q[1],a-b];}

function nulSL2(eta,psi,tilt=0){const ep=Math.exp(eta/2),em=Math.exp(-eta/2),B=[[nulC(ep),nulC()],[nulC(),nulC(em)]],Rz=[[nulC(Math.cos(-psi/2),Math.sin(-psi/2)),nulC()],[nulC(),nulC(Math.cos(psi/2),Math.sin(psi/2))]],c=Math.cos(tilt/2),s=Math.sin(tilt/2),Ry=[[nulC(c),nulC(-s)],[nulC(s),nulC(c)]];return nulMmul(Ry,nulMmul(Rz,B));}

function nulMobius(A,z){return nulCdiv(nulCadd(A[1][0],nulCmul(A[1][1],z)),nulCadd(A[0][0],nulCmul(A[0][1],z)));}

