function nulMaxVec(a,b){return Math.max(...a.map((x,i)=>Math.abs(x-b[i])));}

const civpC=(r=0,i=0)=>({re:r,im:i});

const civpCadd=(a,b)=>civpC(a.re+b.re,a.im+b.im);

const civpCsub=(a,b)=>civpC(a.re-b.re,a.im-b.im);

