  { let w=0; for(let i=0;i<200;i++){ const q=gmodeRandS3(rnd), F=gmodeFrame(q), N=gmodeNullF(2,1,q,0.3); for(const v of [...F,N.E,N.B]) w=Math.max(w,Math.abs(v[0]*q[0]+v[1]*q[1]+v[2]*q[2]+v[3]*q[3])); } push(1,w<1e-13?'PASS':'FAIL',w,1e-13,gmodeFrame); }
