  { const H=[[0,0],[2,1],[3,3]].map(([a,b])=>unifyHelicity(a,b)), w=Math.max(...H.map(h=>Math.abs(h.B2-1))); push(7,w<1e-10?'PASS':'FAIL',H.map(h=>`λ=${h.lambda}: H=${h.H.toFixed(6)}`).join(' · '),1e-10,unifyHelicity,'∫|Re F|² = 1 by exact quadrature; B = Re F is a verified Beltrami field (G04)'); }
  push(8,'DECLARED','no Q_H is computed or shown for a generic P_m',null,null,'the only linking the atlas states is of the zero locus: Hopf fibres, linked once');
  push(9,'DECLARED','M06 and M10 are research, disabled',null,null,'no twistor representative is evaluated without a contour-integral closure');
  push(10,'DECLARED','no VSI claim is made',null,null,'');
  { const f=R=>Math.pow(R,4)/Math.pow(1+R*R,4), v=f(1e3); push(11,v<1e-11?'PASS':'FAIL',v,1e-11,null,'at R = 10³'); }
  { const w=Math.max(...L.map(r=>r.nullDot)); push(12,w<1e-12?'PASS':'FAIL',w,1e-12,gmodeNullF,'E·B is the ABJ source; it vanishes identically on these modes'); }
