const zpPoly=(pts,col,wd=1.4,op=1,dash='')=>pts.length<2?'':
  `<polyline class="zpv" points="${pts.map(p=>p[0].toFixed(2)+','+p[1].toFixed(2)).join(' ')}" stroke="${col}" stroke-width="${wd}" opacity="${op}"${dash?` stroke-dasharray="${dash}"`:''}/>`;

const POLY_PHI=(1+Math.sqrt(5))/2;

const polyQMul=(a,b)=>[a[0]*b[0]-a[1]*b[1]-a[2]*b[2]-a[3]*b[3],
                       a[0]*b[1]+a[1]*b[0]+a[2]*b[3]-a[3]*b[2],
                       a[0]*b[2]-a[1]*b[3]+a[2]*b[0]+a[3]*b[1],
                       a[0]*b[3]+a[1]*b[2]-a[2]*b[1]+a[3]*b[0]];

const polyKey=(a)=>a.map(v=>(Math.abs(v)<1e-12?0:v).toFixed(9)).join(',');

const polyNorm=(a)=>Math.hypot(a[0],a[1],a[2],a[3]);

const POLY_EVEN=Object.freeze([[0,1,2,3],[0,2,3,1],[0,3,1,2],[1,0,3,2],[1,2,0,3],[1,3,2,0],[2,0,1,3],[2,1,3,0],[2,3,0,1],[3,0,2,1],[3,1,0,2],[3,2,1,0]]);

function polyEvenPerms(a){ return POLY_EVEN.map(p=>[a[p[0]],a[p[1]],a[p[2]],a[p[3]]]); }

function polySigns(a){
  const out=[];
  for(let m=0;m<16;m++) out.push(a.map((v,i)=>(m>>i&1)?-v:v));
  return out;
}

function polyUnique(list){
  const m=new Map();
  for(const v of list) if(Math.abs(polyNorm(v)-1)<1e-9) m.set(polyKey(v),v);
  return [...m.values()];
}

function binaryPolyhedral(which){
  const base=polySigns([1,0,0,0]).flatMap(polyEvenPerms);
  const half=polySigns([0.5,0.5,0.5,0.5]);
  if(which==='2T') return polyUnique([...base,...half]);
  if(which==='2O') return polyUnique([...base,...half,
    ...polySigns([Math.SQRT1_2,Math.SQRT1_2,0,0]).flatMap(polyEvenPerms)]);
  if(which==='2I') return polyUnique([...base,...half,
    ...polySigns([0,0.5,0.5/POLY_PHI,POLY_PHI/2]).flatMap(polyEvenPerms)]);
  throw new RangeError(`unknown binary polyhedral group "${which}" — 2T, 2O and 2I are the only three beyond the cyclic and dihedral families`);
}

function polyGroupCheck(G){
  const S=new Set(G.map(polyKey));
  let escapes=0, worstNorm=0;
  for(const a of G){
    worstNorm=Math.max(worstNorm,Math.abs(polyNorm(a)-1));
    for(const b of G) if(!S.has(polyKey(polyQMul(a,b)))) escapes++;
  }
  return {order:G.length, products:G.length*G.length, escapes, worst_norm:worstNorm,
    closed:escapes===0, all_unit:worstNorm<1e-12};
}

function polyShell(G){
  const d=[];
  for(let i=1;i<G.length;i++) d.push(Math.hypot(G[i][0]-G[0][0],G[i][1]-G[0][1],G[i][2]-G[0][2],G[i][3]-G[0][3]));
  d.sort((x,y)=>x-y);
  const first=d[0];
  return {nearest:first, neighbours:d.filter(x=>Math.abs(x-first)<1e-9).length};
}

function polyConjugacyClasses(G){
  const K=G.map(polyKey), idx=new Map(K.map((k,i)=>[k,i]));
  const inv=(q)=>[q[0],-q[1],-q[2],-q[3]];
  const seen=new Array(G.length).fill(false);
  const sizes=[];
  for(let i=0;i<G.length;i++){
    if(seen[i]) continue;
    const orbit=new Set();
    for(const g of G) orbit.add(polyKey(polyQMul(polyQMul(g,G[i]),inv(g))));
    for(const k of orbit){ const j=idx.get(k); if(j!==undefined) seen[j]=true; }
    sizes.push(orbit.size);
  }
  return {classes:sizes.length, sizes:sizes.sort((a,b)=>a-b)};
}

const POLY_MCKAY=Object.freeze({
  '2T':{diagram:'affine E6', nodes:7, marks:Object.freeze([1,2,3,2,1,2,1])},
  '2O':{diagram:'affine E7', nodes:8, marks:Object.freeze([1,2,3,4,3,2,1,2])},
  '2I':{diagram:'affine E8', nodes:9, marks:Object.freeze([1,2,3,4,5,6,4,2,3])}});

function e8Roots(){
  const R=[];
  for(let i=0;i<8;i++) for(let j=i+1;j<8;j++)
    for(const si of [1,-1]) for(const sj of [1,-1]){
      const v=new Array(8).fill(0); v[i]=si; v[j]=sj; R.push(v);
    }
  for(let m=0;m<256;m++){
    const s=[];
    for(let k=0;k<8;k++) s.push((m>>k&1)?-0.5:0.5);
    let neg=0;
    for(const x of s) if(x<0) neg++;
    if(neg%2===0) R.push(s);
  }
  return R;
}

function e8Check(R){
  const n2=(v)=>{ let s=0; for(const x of v) s+=x*x; return s; };
  const dot=(a,b)=>{ let s=0; for(let i=0;i<a.length;i++) s+=a[i]*b[i]; return s; };
  let worstNorm=0, nonInteger=0;
  const values=new Set();
  for(const a of R){
    worstNorm=Math.max(worstNorm,Math.abs(n2(a)-2));
    for(const b of R){ const d=dot(a,b); values.add(Math.round(d));
      if(Math.abs(d-Math.round(d))>1e-12) nonInteger++; }
  }
  return {count:R.length, worst_norm2:worstNorm, non_integer_products:nonInteger,
    inner_products:[...values].sort((a,b)=>a-b), even_unimodular:nonInteger===0&&worstNorm<1e-12};
}

const GOLAY_CIRCULANT=Object.freeze([0,2,6,7,8,10]);

const golayPop=(x)=>{ x=x-((x>>1)&0x55555555); x=(x&0x33333333)+((x>>2)&0x33333333);
  x=(x+(x>>4))&0x0f0f0f0f; return (x*0x01010101)>>24; };

let GOLAY_CACHE=null;

function golayCode(){
  if(GOLAY_CACHE) return GOLAY_CACHE;
  const S=new Set(GOLAY_CIRCULANT), basis=new Int32Array(12);
  let r0=1; for(let j=1;j<=11;j++) r0|=1<<(12+j); basis[0]=r0;
  for(let i=1;i<=11;i++){ let r=(1<<i)|(1<<12);
    for(let j=1;j<=11;j++) if(S.has(((j-i)%11+11)%11)) r|=1<<(12+j);
    basis[i]=r; }
  const words=new Int32Array(4096);
  for(let m=0;m<4096;m++){ let c=0; for(let k=0;k<12;k++) if(m>>k&1) c^=basis[k]; words[m]=c; }
  return (GOLAY_CACHE={basis,words,member:new Set(words)});
}

function golayWeights(){
  const {words}=golayCode(), enumerator={};
  for(let i=0;i<4096;i++){ const w=golayPop(words[i]); enumerator[w]=(enumerator[w]||0)+1; }
  const ws=Object.keys(enumerator).map(Number).sort((a,b)=>a-b);
  return {enumerator, weights:ws, distinct:new Set(words).size,
    min_weight:ws.filter(w=>w>0)[0], all_divisible_by_4:ws.every(w=>w%4===0)};
}

function golaySelfDual(){
  const {basis,words}=golayCode();
  let nonOrth=0;
  for(let i=0;i<12;i++) for(let j=0;j<4096;j++) if(golayPop(basis[i]&words[j])&1) nonOrth++;
  return {pairs:12*4096, non_orthogonal:nonOrth, self_dual:nonOrth===0};
}

function golayOctads(){
  const {words}=golayCode(), out=[];
  for(let i=0;i<4096;i++) if(golayPop(words[i])===8) out.push(words[i]);
  return Int32Array.from(out);
}

function golaySteiner(){
  const oct=golayOctads(), cover=new Map(), p=new Int32Array(8);
  for(let n=0;n<oct.length;n++){
    let t=0; for(let k=0;k<24;k++) if(oct[n]>>k&1) p[t++]=k;
    for(let a=0;a<8;a++)for(let b=a+1;b<8;b++)for(let c=b+1;c<8;c++)for(let d=c+1;d<8;d++)for(let e=d+1;e<8;e++)
      { const key=(p[a]<<20)|(p[b]<<15)|(p[c]<<10)|(p[d]<<5)|p[e];
        cover.set(key,(cover.get(key)||0)+1); }
  }
  const total=24*23*22*21*20/120;
  const mult=[...new Set(cover.values())].sort((a,b)=>a-b);
  return {octads:oct.length, subsets:total, covered:cover.size, multiplicities:mult,
    steiner:cover.size===total&&mult.length===1&&mult[0]===1};
}

function golayPerfect(){
  const {words}=golayCode(), mask=(1<<23)-1, seen=new Set();
  let min=99;
  for(let i=0;i<4096;i++){ const p=words[i]&mask; seen.add(p);
    const w=golayPop(p); if(w>0&&w<min) min=w; }
  const ball=1+23+253+1771;
  return {codewords:seen.size, min_distance:min, ball_radius_3:ball,
    product:seen.size*ball, space:1<<23,
    perfect:seen.size===4096 && min===7 && seen.size*ball===(1<<23)};
}

function leechIn(x){
  const m=x[0]&1;
  let S=0,s=0;
  for(let i=0;i<24;i++){ const v=x[i];
    if((v&1)!==m) return false;
    if(((v-m-2)&3)===0) S|=1<<i;
    s+=v; }
  return golayCode().member.has(S) && ((s-4*m)&7)===0;
}

let LEECH_BASIS=null, LEECH_DET_CACHE=null;

function leechDeterminant(){
  if(LEECH_DET_CACHE) return LEECH_DET_CACHE;
  const {basis}=golayCode(), gens=[];
  for(let i=0;i<12;i++){ const g=new Array(24);
    for(let k=0;k<24;k++) g[k]=(basis[i]>>k&1)?2:0; gens.push(g); }
  for(let i=1;i<24;i++){ const g=new Array(24).fill(0); g[0]=4; g[i]=4; gens.push(g); }
  { const g=new Array(24).fill(1); g[0]=-3; gens.push(g); }
  const outside=gens.filter(g=>!leechIn(g)).length;
  const R=gens.map(r=>r.map(BigInt)), abs=(v)=>v<0n?-v:v;
  let piv=0;
  for(let col=0; col<24 && piv<R.length; col++){
    let k=-1;
    for(let i=piv;i<R.length;i++) if(R[i][col]!==0n && (k<0||abs(R[i][col])<abs(R[k][col]))) k=i;
    if(k<0) continue;
    for(;;){ let m=-1;
      for(let i=piv;i<R.length;i++) if(i!==k&&R[i][col]!==0n){ m=i; break; }
      if(m<0) break;
      const q=R[m][col]/R[k][col];
      for(let j=0;j<24;j++) R[m][j]-=q*R[k][j];
      if(R[m][col]!==0n){ const t=R[m]; R[m]=R[k]; R[k]=t; } }
    const t=R[piv]; R[piv]=R[k]; R[k]=t; piv++;
  }
  let det=1n; for(let i=0;i<piv;i++) det*=abs(R[i][i]);
  LEECH_BASIS=R.slice(0,piv).map(r=>r.map(Number));   /* max |entry| 8956 — exact in doubles */
  return (LEECH_DET_CACHE={generators:gens.length, outside, rank:piv,
    covolume:det.toString(), target:(8n**12n).toString(),
    unimodular:piv===24 && det===8n**12n && outside===0});
}

let LEECH_MINIMAL_CACHE=null;

function leechMinimal(){
  if(LEECH_MINIMAL_CACHE) return LEECH_MINIMAL_CACHE;
  const {words}=golayCode(), oct=golayOctads(), D=leechDeterminant();
  const H=D.unimodular?LEECH_BASIS:null;
  const hpiv=H?H.map(r=>{ let c=0; while(c<24&&r[c]===0) c++; return c; }):null;
  const CAP=1<<19, MASK=CAP-1;
  const K1=new Int32Array(CAP), K2=new Int32Array(CAP), K3=new Int32Array(CAP), USED=new Uint8Array(CAP);
  const x=new Int8Array(24), red=new Float64Array(24);
  /* the first shape, kept, because the projection frame is searched for inside it */
  const A=[];
  for(let i=0;i<24;i++) for(let j=i+1;j<24;j++) for(const si of[4,-4]) for(const sj of[4,-4]){
    const v=new Int8Array(24); v[i]=si; v[j]=sj; A.push(v); }
  const dot=(a,b)=>{ let s=0; for(let k=0;k<24;k++) s+=a[k]*b[k]; return s; };
  const frame=[A[0]];
  for(let a=1;a<A.length&&frame.length<3;a++) if(frame.every(f=>dot(f,A[a])===0)) frame.push(A[a]);
  if(frame.length<3) throw new Error(`no three mutually orthogonal minimal vectors were found among ${A.length} of shape (+-4^2,0^22) — the projection frame is searched for, and if the search fails there is nothing honest to draw`);
  const f0=frame[0], f1=frame[1], f2=frame[2];
  const sites=new Map(), vals=new Set();
  let stored=0, duplicates=0, rejected=0, wrongNorm=0, outside=0, n=0;
  const emit=(shape)=>{
    n++;
    let q=0,h1=0,h2=0,h3=0,pa=0,pb=0,pc=0;
    for(let k=0;k<24;k++){ const v=x[k]; q+=v*v; const c=v+4;
      pa+=v*f0[k]; pb+=v*f1[k]; pc+=v*f2[k];
      if(k<8) h1|=c<<(4*k); else if(k<16) h2|=c<<(4*(k-8)); else h3|=c<<(4*(k-16)); }
    if(q!==32) wrongNorm++;
    if(!leechIn(x)) rejected++;
    let h=((h1*0x9e3779b1)^(h2*0x85ebca6b)^(h3*0xc2b2ae35))&MASK;
    for(;;){ if(!USED[h]){ USED[h]=1; K1[h]=h1; K2[h]=h2; K3[h]=h3; stored++; break; }
      if(K1[h]===h1&&K2[h]===h2&&K3[h]===h3){ duplicates++; break; }
      h=(h+1)&MASK; }
    if(H){
      for(let k=0;k<24;k++) red[k]=x[k];
      let out=false;
      for(let i=0;i<H.length&&!out;i++){ const c=hpiv[i]; if(c>=24) continue;
        const t=red[c]/H[i][c];
        if(!Number.isInteger(t)){ out=true; break; }
        if(t!==0){ const row=H[i]; for(let j=c;j<24;j++) red[j]-=t*row[j]; } }
      if(!out) for(let k=0;k<24;k++) if(red[k]!==0){ out=true; break; }
      if(out) outside++;
    }
    vals.add(pa); vals.add(pb); vals.add(pc);
    const key=pa+','+pb+','+pc;
    let s=sites.get(key);
    if(!s){ s={a:pa,b:pb,c:pc,mult:0,byShape:[0,0,0]}; sites.set(key,s); }
    s.mult++; s.byShape[shape]++;
  };
  for(const v of A){ x.set(v); emit(0); }
  const shapeA=n;
  const p=new Int32Array(8);
  for(let t=0;t<oct.length;t++){
    let q=0; for(let k=0;k<24;k++) if(oct[t]>>k&1) p[q++]=k;
    for(let s=0;s<256;s++){ if(golayPop(s)&1) continue;
      x.fill(0);
      for(let k=0;k<8;k++) x[p[k]]=(s>>k&1)?-2:2;
      emit(1); }
  }
  const shapeB=n;
  for(let i=0;i<24;i++) for(let c=0;c<4096;c++){ const w=words[c];
    for(let k=0;k<24;k++) x[k]=(w>>k&1)?-1:1;
    x[i]=(w>>i&1)?3:-3;
    emit(2); }
  let accounted=0; for(const s of sites.values()) accounted+=s.mult;
  return (LEECH_MINIMAL_CACHE={shape_4_4:shapeA, shape_2_8:shapeB-shapeA, shape_3_1:n-shapeB,
    total:n, distinct:stored, duplicates, rejected, wrong_norm:wrongNorm,
    outside_the_span:H?outside:-1,
    kissing:(rejected===0&&wrongNorm===0&&duplicates===0&&(H!=null&&outside===0))?n:-1,
    crystal:{frame:frame.map(f=>Array.from(f)), sites:[...sites.values()], total:n,
      accounted, values:[...vals].sort((u,v)=>u-v), exhaustive:accounted===n&&n===196560}});
}

function leechMinNorm(){
  const {words}=golayCode(), W=golayWeights();
  let norm24=0, light=0, short4=0;
  for(let i=0;i<4096;i++){ const w=golayPop(words[i]);
    if(((24-2*w-4)&7)===0) norm24++;
    if(w>0&&w<8) light++; }
  const x=new Int8Array(24);
  for(let i=0;i<24;i++) for(const s of[4,-4]){ x.fill(0); x[i]=s; if(leechIn(x)) short4++; }
  return {golay_min_weight:W.min_weight, golay_weights_divisible_by_4:W.all_divisible_by_4,
    codewords_admitting_norm_24:norm24, codewords_of_weight_1_to_7:light,
    lattice_vectors_of_shape_4:short4,
    min_norm_is_4:norm24===0&&light===0&&short4===0};
}

const OSC_C=2.99792458e8;

const OSC_V_AIR=343.0;

const OSC_QMAX=3e5, OSC_TAIL=6;

function oscContFrac(x,QMAX){
  QMAX=QMAX||OSC_QMAX;
  const terms=[], cv=[]; let v=x, pm1=1,pm2=0,qm1=0,qm2=1, stopped='budget';
  for(let k=0;k<80;k++){
    const t=Math.floor(v);
    const p=t*pm1+pm2, q=t*qm1+qm2;
    if(!Number.isFinite(q)||q>QMAX){ stopped='cap'; break; }
    terms.push(t); cv.push({p,q,d:q*Math.abs(q*x-p)});
    pm2=pm1; pm1=p; qm2=qm1; qm1=q;
    const r=v-t; if(r<=0){ stopped='terminated'; break; }
    v=1/r;
  }
  /* WHY THE EXPANSION STOPPED IS NOT A DETAIL, and not recording it was a real error
     for as long as this shipped. Stopping because the remainder went to zero means the
     number IS the fraction p/q. Stopping because the denominator passed the cap means
     nothing of the sort — it means the cap arrived first — and the two were reported
     identically as "rational". A ratio between two independently computed physical
     quantities is essentially never rational, and telling a reader that it is says the
     two phenomena return to phase exactly and forever, which is a claim about the world
     made by an arithmetic limit. */
  return {terms, convergents:cv, stopped};
}

function oscLagrange(x,QMAX,TAIL){
  TAIL=TAIL||OSC_TAIL;
  const {convergents:cv,terms,stopped}=oscContFrac(x,QMAX);
  if(cv.length<TAIL+2) return {L:NaN, liminf:NaN, tail:cv.length, terms:terms.length,
    stopped, rational:(stopped==='terminated'), capped:(stopped==='cap'),
    last:cv[cv.length-1]||null, denominators:cv.map(c=>c.q)};
  const use=cv.slice(cv.length-TAIL);
  let mn=Infinity; for(const c of use) if(c.d<mn) mn=c.d;
  return {L:mn>0?1/mn:Infinity, liminf:mn, tail:use.length, terms:terms.length,
    stopped, rational:false, capped:(stopped==='cap'),
    exact_at_double:(mn===0)?use.find(c=>c.d===0):null,
    max_partial_quotient:Math.max(...terms.slice(1)),
    denominators:cv.map(c=>c.q), sequence:cv.map(c=>c.d)};
}

function oscThreeDistance(alpha,N){
  const a=new Float64Array(N+1);
  for(let k=1;k<=N;k++){ let v=(k*alpha)%1; if(v<0)v+=1; a[k-1]=v; }
  a[N]=0;
  a.sort();
  const uniq=[];
  let over=0;
  for(let i=1;i<=N;i++){
    const g=a[i]-a[i-1];
    if(g<=1e-12) continue;
    let seen=false;
    for(const u of uniq) if(Math.abs(u-g)<1e-9){ seen=true; break; }
    if(!seen){ if(uniq.length<8) uniq.push(g); else over++; }
  }
  { const g=1-a[N];
    if(g>1e-12){ let seen=false; for(const u of uniq) if(Math.abs(u-g)<1e-9) seen=true;
      if(!seen){ if(uniq.length<8) uniq.push(g); else over++; } } }
  return {n:N, distinct:uniq.length+over, lengths:uniq.sort((x,y)=>x-y)};
}

function oscFirstCoincidence(alpha,eps,maxN){
  maxN=maxN||1e6;
  for(let k=1;k<=maxN;k++){ let v=(alpha*k)%1; if(v<0)v+=1;
    if(v<eps||v>1-eps) return k; }
  return -1;
}

const OSC_FIB=(()=>{ const s=new Set(); let a=1,b=2;
  for(let i=0;i<44;i++){ s.add(a); const n=a+b; a=b; b=n; } return s; })();

const HCC_BANDS=Object.freeze({
  electromagnetic:Object.freeze([
    {name:'radio',       lo:3e3,   hi:3e9},
    {name:'microwave',   lo:3e9,   hi:3e11},
    {name:'infrared',    lo:3e11,  hi:4.3e14},
    {name:'visible',     lo:4.3e14,hi:7.5e14},
    {name:'ultraviolet', lo:7.5e14,hi:3e16},
    {name:'X-ray',       lo:3e16,  hi:3e19},
    {name:'gamma',       lo:3e19,  hi:3e22}]),
  acoustic:Object.freeze([
    {name:'infrasound',  lo:1e-3,  hi:20},
    {name:'audible',     lo:20,    hi:2e4},
    {name:'ultrasound',  lo:2e4,   hi:1e9},
    {name:'hypersound',  lo:1e9,   hi:1e13}])
});

function oscBandOf(f,ladder){
  const L=HCC_BANDS[ladder]; if(!L) return null;
  for(const b of L) if(f>=b.lo&&f<b.hi) return b;
  return null;
}

function oscWavelength(f,ladder){
  if(!(f>0)) return NaN;
  return (ladder==='acoustic'?OSC_V_AIR:OSC_C)/f;
}

const OSC_TAU=2*Math.PI;

const oscStep=(t,O,K)=>t+O-(K/OSC_TAU)*Math.sin(OSC_TAU*t);

function oscRotation(O,K,N,skip){
  let t=0.5;
  for(let i=0;i<skip;i++) t=oscStep(t,O,K);
  const t0=t;
  for(let i=0;i<N;i++) t=oscStep(t,O,K);
  return (t-t0)/N;
}

function oscLocked(O,K,QMAX,tol){
  let t=0.5;
  for(let i=0;i<600;i++) t=oscStep(t,O,K);
  const base=t;
  for(let q=1;q<=QMAX;q++){
    t=oscStep(t,O,K);
    const d=t-base, p=Math.round(d);
    if(Math.abs(d-p)<tol) return {q,p};
  }
  return null;
}

const OSC_OFF=2-(1+Math.sqrt(5))/2;

const oscOmegaAt=(i,n)=>((i+OSC_OFF)/n)%1;

function oscLockedFraction(K,samples,QMAX,tol){
  let n=0;
  for(let i=0;i<samples;i++) if(oscLocked(oscOmegaAt(i,samples),K,QMAX,tol)) n++;
  return {K, samples, QMAX, locked:n, fraction:n/samples};
}

const CD_CONJ=(a)=>a.map((v,i)=>i?-v:v);

const CD_ADD=(a,b)=>a.map((v,i)=>v+b[i]);

const CD_NEG=(a)=>a.map(v=>-v);

const CD_DOT=(a,b)=>{ let s=0; for(let i=0;i<a.length;i++) s+=a[i]*b[i]; return s; };

const CD_NORM=(a)=>Math.sqrt(CD_DOT(a,a));

function cdMul(x,y){
  const n=x.length;
  if(n===1) return [x[0]*y[0]];
  const h=n>>1;
  const a=x.slice(0,h), b=x.slice(h), c=y.slice(0,h), d=y.slice(h);
  const l=CD_ADD(cdMul(a,c), CD_NEG(cdMul(CD_CONJ(d),b)));
  const r=CD_ADD(cdMul(d,a), cdMul(b,CD_CONJ(c)));
  return l.concat(r);
}

const CD_NAMES=Object.freeze({1:'real',2:'complex',4:'quaternion',8:'octonion',16:'sedenion',32:'trigintaduonion'});

function cdProperties(dim,samples){
  const N=Math.max(8,samples|0);
  const gen=(s)=>Array.from({length:dim},(_,i)=>Math.sin(s*7.1+i*2.3)+0.3*Math.cos(s*3.7+i));
  let normDefect=0, assoc=0, alt=0, comm=0, moufang=0, zeroDiv=0;
  for(let s=1;s<=N;s++){
    const x=gen(s), y=gen(s+0.5), z=gen(s+0.9);
    const nx=CD_NORM(x), ny=CD_NORM(y);
    if(nx>0&&ny>0) normDefect=Math.max(normDefect, Math.abs(CD_NORM(cdMul(x,y))-nx*ny)/(nx*ny));
    const A=cdMul(cdMul(x,y),z), B=cdMul(x,cdMul(y,z));
    assoc=Math.max(assoc, CD_NORM(CD_ADD(A,CD_NEG(B)))/Math.max(1,CD_NORM(A)));
    const C=cdMul(cdMul(x,x),y), D=cdMul(x,cdMul(x,y));
    alt=Math.max(alt, CD_NORM(CD_ADD(C,CD_NEG(D)))/Math.max(1,CD_NORM(C)));
    const E=cdMul(x,y), F=cdMul(y,x);
    comm=Math.max(comm, CD_NORM(CD_ADD(E,CD_NEG(F)))/Math.max(1,CD_NORM(E)));
    const M1=cdMul(cdMul(x,y),cdMul(z,x)), M2=cdMul(cdMul(x,cdMul(y,z)),x);
    moufang=Math.max(moufang, CD_NORM(CD_ADD(M1,CD_NEG(M2)))/Math.max(1,CD_NORM(M1)));
  }
  const TOL=1e-12;
  return {dimension:dim, name:CD_NAMES[dim]||('2^'+Math.log2(dim)),
    norm_defect:normDefect, associator:assoc, alternator:alt, commutator:comm, moufang_defect:moufang,
    is_division:normDefect<TOL, is_associative:assoc<TOL, is_alternative:alt<TOL,
    is_commutative:comm<TOL, is_moufang:moufang<TOL};
}

function cdHopf(p){
  const n=p.length>>1;
  const a=p.slice(0,n), b=p.slice(n);
  const ab=cdMul(a,CD_CONJ(b));
  return ab.map(v=>2*v).concat([CD_DOT(a,a)-CD_DOT(b,b)]);
}

function cdSphereIsGroup(dim,samples){
  const N=Math.max(8,samples|0);
  const gen=(s)=>{ const v=Array.from({length:dim},(_,i)=>Math.sin(s*5.3+i*1.7)+0.4*Math.cos(s*2.9+i));
    const L=CD_NORM(v); return v.map(q=>q/L); };
  let closed=0, assoc=0, inv=0;
  for(let s=1;s<=N;s++){
    const x=gen(s), y=gen(s+0.6), z=gen(s+1.3);
    closed=Math.max(closed, Math.abs(CD_NORM(cdMul(x,y))-1));
    const A=cdMul(cdMul(x,y),z), B=cdMul(x,cdMul(y,z));
    assoc=Math.max(assoc, CD_NORM(CD_ADD(A,CD_NEG(B))));
    const e=cdMul(x,CD_CONJ(x));
    inv=Math.max(inv, Math.abs(e[0]-1)+Math.hypot(...e.slice(1)));
  }
  const TOL=1e-12;
  return {sphere:'S^'+(dim-1), closed:closed<TOL, has_inverses:inv<TOL,
    associative:assoc<TOL, associator:assoc,
    structure: closed<TOL&&inv<TOL ? (assoc<TOL?'group':'Moufang loop, not a group') : 'not closed'};
}

const MIX_S3=Math.sqrt(3);

const mixW =(bp,bm)=> Math.exp(-8*bp) - 4*Math.exp(-2*bp)*Math.cosh(2*MIX_S3*bm)
                    + 2*Math.exp(4*bp)*(Math.cosh(4*MIX_S3*bm)-1);

const mixWp=(bp,bm)=> -8*Math.exp(-8*bp) + 8*Math.exp(-2*bp)*Math.cosh(2*MIX_S3*bm)
                    + 8*Math.exp(4*bp)*(Math.cosh(4*MIX_S3*bm)-1);

const mixWm=(bp,bm)=> -8*MIX_S3*Math.exp(-2*bp)*Math.sinh(2*MIX_S3*bm)
                    + 8*MIX_S3*Math.exp(4*bp)*Math.sinh(4*MIX_S3*bm);

const mixH=(y)=> 0.5*(-y[3]*y[3]+y[4]*y[4]+y[5]*y[5]) + Math.exp(-4*y[0])*mixW(y[1],y[2]);

const MIX_W=Object.freeze([-0.161582374150097e1,-0.244699182370524e1,-0.716989419708120e-2,0.244002732616735e1,0.157739928123617e0,0.182020630970714e1,0.104242620869991e1]);

const MIX_W0=1-2*MIX_W.reduce((a,b)=>a+b,0);

const MIX_SEQ=Object.freeze([MIX_W[6],MIX_W[5],MIX_W[4],MIX_W[3],MIX_W[2],MIX_W[1],MIX_W[0],MIX_W0,MIX_W[0],MIX_W[1],MIX_W[2],MIX_W[3],MIX_W[4],MIX_W[5],MIX_W[6]]);

function mixLeap(y,h){
  const a=h/2;
  y[0]+=a*(-y[3]); y[1]+=a*y[4]; y[2]+=a*y[5];
  const e=Math.exp(-4*y[0]);
  y[3]+=h*(4*e*mixW(y[1],y[2])); y[4]-=h*(e*mixWp(y[1],y[2])); y[5]-=h*(e*mixWm(y[1],y[2]));
  y[0]+=a*(-y[3]); y[1]+=a*y[4]; y[2]+=a*y[5];
}

function mixY8(y,h){ for(let i=0;i<15;i++) mixLeap(y,MIX_SEQ[i]*h); return y; }

function mixEvolve(y0,tau,h){
  const y=Float64Array.from(y0); const H0=mixH(y);
  let t=0, worst=0, steps=0, sing=null;
  const n=Math.max(1,Math.round(tau/h));
  for(let i=0;i<n;i++){
    mixY8(y,h); t+=h; steps++;
    if(!Number.isFinite(y[0])||!Number.isFinite(y[3])||y[0]<-30){ sing=t; break; }
    const d=Math.abs(mixH(y)-H0); if(Number.isFinite(d)&&d>worst) worst=d;
  }
  return {y:Array.from(y), tau:t, steps, H0, dH:worst, singular:sing!==null, tau_singular:sing};
}

function mixLyapunov(y0,T,h){
  const a=Float64Array.from(y0), b=Float64Array.from(y0); const d0=1e-9;
  b[4]+=d0; let sum=0; const n=Math.max(1,Math.round(T/h));
  for(let i=0;i<n;i++){
    mixY8(a,h); mixY8(b,h);
    let d=0; for(let k=0;k<6;k++){ const q=b[k]-a[k]; d+=q*q; }
    d=Math.sqrt(d);
    if(!(d>0)||!Number.isFinite(d)) return NaN;
    sum+=Math.log(d/d0); const s=d0/d;
    for(let k=0;k<6;k++) b[k]=a[k]+(b[k]-a[k])*s;
  }
  return sum/T;
}

function mixLyapunovClass(y0,T,h){
  const l1=mixLyapunov(y0,T,h), l2=mixLyapunov(y0,2*T,h);
  const ratio=l2/l1;
  let verdict='inconclusive';
  if(!Number.isFinite(ratio)) verdict='singular before the window closed';
  else if(l1>0.01&&Math.abs(ratio-1)<0.12) verdict='chaotic plateau';
  else if(Number.isFinite(l1)&&l2<0.85*l1) verdict='decaying like ln T / T — no plateau in this time variable';
  return {lambda_T:l1, lambda_2T:l2, ratio, verdict};
}

