      schwarzschild_radius_au:rsAU, isco_radius_au:3*rsAU,
      salpeter_time_yr:4.5e8*(i.radiative_efficiency/(1-i.radiative_efficiency))/i.eddington_ratio,
      isco_efficiency_closed_form:QSO_ETA,
